function vnSkenario(){ try{ var s = localStorage.getItem('slvn_skenario'); if(['A', 'B', 'M', 'AF', 'BF'].indexOf(s) >= 0) return s; }catch(e){} return 'A'; }
function vnFokus(){ try{ var f = localStorage.getItem('slvn_fokus'); if(f === 'SEMUA' || f === 'HUNTER') return f; }catch(e){} return 'HUNTER'; }
function vnSiklusMulai(){ try{ var s = localStorage.getItem('slvn_siklus_mulai'); if(/^\d{4}-\d{2}-\d{2}$/.test(s || '')) return s; }catch(e){} return VN_SIKLUS_MULAI; }
